private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int pos = i;
    if (pos >= bb.limit()) {
        return pos;
    }
    int firstByte = bb.get(pos) & 0xFF;
    int decodedLen = 1;
    int cp = 0xFFFD; // replacement character

    if ((firstByte & 0x80) == 0) { // 1-byte sequence
        cp = firstByte;
        decodedLen = 1;
    } else if ((firstByte & 0xE0) == 0xC0) { // 2-byte sequence
        if (pos + 1 < bb.limit()) {
            int secondByte = bb.get(pos + 1) & 0xFF;
            cp = ((firstByte & 0x1F) << 6) | (secondByte & 0x3F);
            decodedLen = 2;
        }
    } else if ((firstByte & 0xF0) == 0xE0) { // 3-byte sequence
        if (pos + 2 < bb.limit()) {
            int secondByte = bb.get(pos + 1) & 0xFF;
            int thirdByte = bb.get(pos + 2) & 0xFF;
            cp = ((firstByte & 0x0F) << 12) | ((secondByte & 0x3F) << 6) | (thirdByte & 0x3F);
            decodedLen = 3;
        }
    } else if ((firstByte & 0xF8) == 0xF0) { // 4-byte sequence
        if (pos + 3 < bb.limit()) {
            int secondByte = bb.get(pos + 1) & 0xFF;
            int thirdByte = bb.get(pos + 2) & 0xFF;
            int fourthByte = bb.get(pos + 3) & 0xFF;
            int codePoint = ((firstByte & 0x07) << 18) | ((secondByte & 0x3F) << 12)
                    | ((thirdByte & 0x3F) << 6) | (fourthByte & 0x3F);
            // Will handle surrogate pairs below
            cp = codePoint;
            decodedLen = 4;
        }
    }

    if (decodedLen == 4 && cp >= 0x10000) {
        int t = cp - 0x10000;
        sb.append((char) ((t >>> 10) + 0xD800));
        sb.append((char) ((t & 0x3FF) + 0xDC00));
    } else {
        sb.append((char) cp);
    }
    return pos + decodedLen;
}

