public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                sb.append('\\');
                break;
            }
            char next = str.charAt(i + 1);
            if (next == '\\') {
                sb.append('\\');
                i++; // skip the escaped backslash
            } else {
                i++; // consume escape char
                switch (next) {
                    case 'n':
                        sb.append('\n');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 'b':
                        sb.append('\b');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case '\'':
                        sb.append('\'');
                        break;
                    case '\"':
                        sb.append('\"');
                        break;
                    case '0':
                        sb.append('\0');
                        break;
                    case 'u':
                        if (i + 4 >= len)
                            throw new IllegalArgumentException("Invalid unicode escape sequence at index " + (i - 1));
                        String hex = str.substring(i + 1, i + 5);
                        try {
                            sb.append((char) Integer.parseInt(hex, 16));
                        } catch (NumberFormatException e) {
                            throw new IllegalArgumentException("Invalid unicode escape sequence: \\u" + hex, e);
                        }
                        i += 4; // skip 4 hex digits
                        break;
                    default:
                        sb.append(next);
                        break;
                }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

